// Writes src/do/workspace/methods.gen.ts: one WorkspaceDO RPC method per workspace server
// function (02, WorkspaceDO RPC). Workers RPC exposes prototype methods only.
import { writeFileSync } from "node:fs";
import { WORKSPACE_FNS } from "@tempo/protocol";

const lines = [
  "// Generated by scripts/gen-do-methods.ts. Do not edit by hand.",
  'import { DurableObject } from "cloudflare:workers";',
  'import type { FnOutput, Result, WorkspaceFnName } from "@tempo/protocol";',
  'import type { Env } from "../../env.ts";',
  'import type { MethodInput } from "./rpc.ts";',
  "",
  "export abstract class WorkspaceRpcBase extends DurableObject<Env> {",
  "  protected abstract rpc<K extends WorkspaceFnName>(name: K, input: MethodInput<K>): Promise<Result<FnOutput<K>>>;",
  "",
];

for (const name of WORKSPACE_FNS) {
  lines.push(
    `  ${name}(input: MethodInput<"${name}">): Promise<Result<FnOutput<"${name}">>> {`,
    `    return this.rpc("${name}", input);`,
    "  }",
    "",
  );
}

lines.push("}", "");

writeFileSync(new URL("../src/do/workspace/methods.gen.ts", import.meta.url), lines.join("\n"));

console.log(`wrote ${WORKSPACE_FNS.length} methods`);
